[{"order":1,"type":"heading","text":"Handling Unhandled Rejections and Uncaught Exceptions in Express.js"},{"order":2,"type":"paragraph","text":"Building robust Node.js and Express.js applications requires proper error management. While standard try/catch blocks handle synchronous errors and Express next() functions handle asynchronous middleware errors, application stability can still be compromised by unhandled promise rejections and uncaught exceptions."},{"order":3,"type":"subheading","text":"Understanding the Differences"},{"order":4,"type":"bullet_point","text":"Uncaught Exception: Occurs when an error is thrown synchronously and it is not caught anywhere in the call stack. This leaves the application in an undefined, potentially corrupted state."},{"order":5,"type":"bullet_point","text":"Unhandled Rejection: Occurs when a JavaScript Promise is rejected, but there is no .catch() handler attached to deal with the failure. Historically, this caused silent failures, but in modern Node.js versions, it triggers a process warning and eventually crashes the application."},{"order":6,"type":"subheading","text":"Global Process Event Listeners"},{"order":7,"type":"paragraph","text":"To prevent unexpected crashes and ensure clean shutdowns, you must listen to global process events at the very entry point of your application (usually server.js or app.js)."},{"order":8,"type":"code","text":"const express = require('express');
const app = express();

// Handle Uncaught Exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Dummy route to simulate normal functionality
app.get('/', (req, res) => {
  res.send('Hello World');
});

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle Unhandled Promise Rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});"},{"order":9,"type":"subheading","text":"Best Practices for Production Environments"},{"order":10,"type":"bullet_point","text":"Always gracefully close your HTTP server using server.close() before exiting the process on unhandled rejections. This allows ongoing requests to finish processing."},{"order":11,"type":"bullet_point","text":"Use a process manager like PM2, Kubernetes, or Docker to automatically restart your Node.js application after it exits due to a fatal error."},{"order":12,"type":"bullet_point","text":"Never attempt to resume normal execution after an uncaught exception, as the application memory and state may be severely compromised."}]
